async () => {
  // 清理旧仿真层
  document.getElementById('__bp_sim')?.remove();
  const W = 1024, H = 900;
  const scale = Math.min(1, (window.innerWidth - 4) / W);
  const wrap = document.createElement('div');
  wrap.id = '__bp_sim';
  wrap.style.cssText = `position:fixed;inset:0;z-index:99999;background:#111;overflow:hidden;`;
  const f = document.createElement('iframe');
  f.id = '__bp_frame';
  f.style.cssText = `width:${W}px;height:${H}px;border:0;transform:scale(${scale});transform-origin:top left;display:block;background:#fff;`;
  f.src = location.origin + '/';
  wrap.appendChild(f);
  document.body.appendChild(wrap);
  await new Promise(res => { f.onload = () => res(); setTimeout(res, 8000); });
  // 等 SPA 渲染
  await new Promise(r => setTimeout(r, 2500));
  const doc = f.contentDocument;
  const header = doc.querySelector('header');
  return {
    scale,
    frameInnerWidth: f.contentWindow.innerWidth,
    headerFound: !!header,
    title: doc.title,
    bodyText: doc.body ? doc.body.innerText.slice(0, 120) : ''
  };
}

() => {
  const f = document.getElementById('__bp_frame');
  if (!f) return { frameExists: false };
  let access = 'unknown';
  try { access = f.contentDocument ? 'accessible' : 'null-doc'; } catch (e) { access = 'blocked: ' + e.message; }
  return { frameExists: true, access, src: f.src };
}

async () => {
  const r = await fetch('/', { method: 'GET' });
  const h = {};
  ['x-frame-options', 'content-security-policy'].forEach(k => h[k] = r.headers.get(k));
  return h;
}

