() => {
  const mediaTexts = new Set();
  let sheetCount = 0, ruleCount = 0, err = [];
  for (const sheet of document.styleSheets) {
    sheetCount++;
    let rules;
    try { rules = sheet.cssRules; } catch (e) { err.push(sheet.href || 'inline'); continue; }
    const walk = (list) => {
      for (const r of list) {
        if (r instanceof CSSMediaRule) { mediaTexts.add(r.media.mediaText); ruleCount++; walk(r.cssRules); }
        else if (r.cssRules) walk(r.cssRules);
      }
    };
    walk(rules);
  }
  return { sheetCount, mediaRuleCount: ruleCount, mediaTexts: [...mediaTexts], inaccessible: err };
}

async () => {
  const W = 1024;
  const REM = 16; // 媒体查询中 rem 按初始字号 16px 计算
  document.getElementById('__bpsim')?.remove();
  document.getElementById('__bpsim-style')?.remove();

  // 1. 收集所有宽度型媒体规则，筛选目标宽度下应生效的规则体
  const widthRules = [];
  const parse = (mt) => {
    // 形如 "(width >= 64rem)" / "(min-width: 64rem)" 等
    const m = mt.match(/(?:width\s*>=\s*|min-width:\s*)([\d.]+)(rem|px)/);
    if (m) { const px = m[2] === 'rem' ? parseFloat(m[1]) * REM : parseFloat(m[1]); return { type: 'min', px }; }
    const m2 = mt.match(/(?:width\s*<=\s*|max-width:\s*)([\d.]+)(rem|px)/);
    if (m2) { const px = m2[2] === 'rem' ? parseFloat(m2[1]) * REM : parseFloat(m2[1]); return { type: 'max', px }; }
    return null;
  };
  const walk = (list) => {
    for (const r of list) {
      if (r instanceof CSSMediaRule) {
        const c = parse(r.media.mediaText);
        if (c) {
          const match = c.type === 'min' ? W >= c.px : W <= c.px;
          if (match) for (const inner of r.cssRules) widthRules.push(inner.cssText);
        }
        walk(r.cssRules);
      } else if (r.cssRules) walk(r.cssRules);
    }
  };
  for (const sheet of document.styleSheets) { try { walk(sheet.cssRules); } catch (e) {} }

  // 2. 将命中的规则限定作用于克隆容器，避免污染真实页面
  const scopeCss = (cssText) => {
    // cssText 形如 ".md\\:flex{display:flex}"；仅处理选择器前缀
    const i = cssText.indexOf('{');
    const selPart = cssText.slice(0, i).trim();
    const rest = cssText.slice(i);
    const scoped = selPart.split(',').map(s => `[data-bpclone] ${s.trim()}`).join(',');
    return scoped + rest;
  };
  const styleEl = document.createElement('style');
  styleEl.id = '__bpsim-style';
  styleEl.textContent = widthRules.map(scopeCss).join('\n');
  document.head.appendChild(styleEl);

  // 3. 克隆 header 到 W 宽容器（先离屏测量）
  const realHeader = document.querySelector('header');
  const container = document.createElement('div');
  container.id = '__bpsim';
  container.setAttribute('data-bpclone', '');
  container.style.cssText = `position:fixed;left:-20000px;top:0;width:${W}px;z-index:999999;`;
  const clone = realHeader.cloneNode(true);
  container.appendChild(clone);
  document.body.appendChild(container);
  await new Promise(r => setTimeout(r, 300)); // 等样式应用

  // 4. 测量
  const cs = (el) => getComputedStyle(el);
  const headerRect = clone.getBoundingClientRect();
  const overflowX = clone.scrollWidth - clone.clientWidth;
  const containerOverflowX = container.scrollWidth - container.clientWidth;

  const logoutBtn = clone.querySelector('button[title="退出登录"]');
  const logoutRect = logoutBtn.getBoundingClientRect();
  const logoutRightRel = +(logoutRect.right - headerRect.left).toFixed(2);
  const logoutVisible = cs(logoutBtn).display !== 'none' && cs(logoutBtn).visibility !== 'hidden';

  const badge = [...clone.querySelectorAll('span')].find(s => s.textContent.includes('NL2SQL Pro'));
  const badgeDisplay = badge ? cs(badge).display : 'NOT-FOUND';

  const unitSelect = clone.querySelector('select[data-testid="global-amount-unit-select"]');
  const unitWrap = unitSelect ? unitSelect.parentElement : null;
  const unitDisplay = unitWrap ? cs(unitWrap).display : 'NOT-FOUND';
  const unitRect = unitWrap ? unitWrap.getBoundingClientRect() : null;

  const dsSelect = clone.querySelector('select[data-testid="datasource-select"]');
  const dsWrap = dsSelect ? dsSelect.parentElement : null;
  const dsDisplay = dsWrap ? cs(dsWrap).display : 'NOT-FOUND';

  // 5. Range.getClientRects 逐文本节点检测折行
  const wrapped = [];
  const checkedNodes = [];
  const walker = document.createTreeWalker(clone, NodeFilter.SHOW_TEXT);
  let node;
  const range = document.createRange();
  while ((node = walker.nextNode())) {
    const txt = node.textContent;
    if (!txt || !txt.trim()) continue;
    const parent = node.parentElement;
    if (!parent) continue;
    const pcs = cs(parent);
    if (pcs.display === 'none' || pcs.visibility === 'hidden') continue;
    // 祖先链 display 检查
    let anc = parent, hidden = false;
    while (anc && anc !== container) { if (cs(anc).display === 'none') { hidden = true; break; } anc = anc.parentElement; }
    if (hidden) continue;
    if (parent.closest('select,option,script,style')) continue;
    range.selectNodeContents(node);
    const rects = range.getClientRects();
    const lines = rects.length;
    const label = txt.trim().slice(0, 30);
    checkedNodes.push({ text: label, lines });
    if (lines > 1) wrapped.push({ text: label, lines });
  }

  // 6. 摆回可视区并缩放以适配当前视口（供截图）
  const scale = Math.min(1, (window.innerWidth - 8) / W);
  container.style.left = '4px';
  container.style.transform = `scale(${scale})`;
  container.style.transformOrigin = 'top left';
  container.style.background = getComputedStyle(document.body).backgroundColor || '#0f172a';
  container.style.outline = '2px solid #22d3ee';

  return {
    targetWidth: W,
    appliedMediaRules: widthRules.length,
    header: { clientWidth: clone.clientWidth, scrollWidth: clone.scrollWidth, overflowX },
    container: { clientWidth: container.clientWidth, scrollWidth: container.scrollWidth, overflowX: containerOverflowX },
    logoutBtn: { visible: logoutVisible, rightRelToHeader: logoutRightRel, withinBounds: logoutRightRel <= W },
    versionBadge: { display: badgeDisplay, visibleAtThisWidth: badgeDisplay !== 'none' && badgeDisplay !== 'NOT-FOUND' },
    amountUnitSelector: { display: unitDisplay, visible: unitDisplay === 'flex', width: unitRect ? +unitRect.width.toFixed(1) : null },
    datasourceSwitcher: { display: dsDisplay },
    textCheck: { totalTextNodes: checkedNodes.length, wrappedCount: wrapped.length, wrapped },
    sampleChecked: checkedNodes.slice(0, 12),
    scale
  };
}

() => {
  const container = document.getElementById('__bpsim');
  const clone = container.querySelector('header');
  const subtitle = clone.querySelector('p');
  const h1 = clone.querySelector('h1');
  const reportBtnSpan = [...clone.querySelectorAll('span')].find(s => s.textContent.trim() === '自动生成报表');
  const dsBtnSpan = [...clone.querySelectorAll('span')].find(s => s.textContent.trim() === '接入数据源');
  const allText = [];
  const walker = document.createTreeWalker(clone, NodeFilter.SHOW_TEXT);
  let n; while ((n = walker.nextNode())) { if (n.textContent.trim()) allText.push(n.textContent.trim().slice(0, 24)); }
  return {
    subtitleDisplay: subtitle ? getComputedStyle(subtitle).display : 'N/A',
    subtitleText: subtitle ? subtitle.textContent.trim() : '',
    h1Display: getComputedStyle(h1).display,
    reportSpanDisplay: reportBtnSpan ? getComputedStyle(reportBtnSpan).display : 'N/A',
    dsSpanDisplay: dsBtnSpan ? getComputedStyle(dsBtnSpan).display : 'N/A',
    allTextNodes: allText
  };
}

() => {
  const styleEl = document.getElementById('__bpsim-style');
  const css = styleEl.textContent;
  const hasSmBlock = css.includes('sm\\:block');
  const hasMdFlex = css.includes('md\\:flex');
  const hasLgFlex = css.includes('lg\\:flex');
  // 找出所有包含 sm\: 的规则片段
  const smSnippets = css.split('\n').filter(l => l.includes('sm\\:')).slice(0, 5);
  return { cssLen: css.length, hasSmBlock, hasMdFlex, hasLgFlex, smSnippets, head: css.slice(0, 300) };
}

