() => {
  const container = document.getElementById('__bpsim');
  const p = container.querySelector('p');
  const result = {
    className: p.className,
    hasSmBlockClass: p.classList.contains('sm:block'),
    matchesScoped: p.matches('[data-bpclone] .sm\\:block'),
    computedDisplay: getComputedStyle(p).display
  };
  // 检查 .hidden 与 .sm\:block 规则是否在 @layer 中（分层样式优先级低于未分层）
  const checkLayer = (cls) => {
    for (const sheet of document.styleSheets) {
      const walk = (rules, layers) => {
        for (const r of rules) {
          const l2 = r instanceof CSSLayerBlockRule ? [...layers, r.name] : layers;
          if (r instanceof CSSStyleRule && r.selectorText === cls) return { found: true, layers: l2 };
          if (r.cssRules) { const f = walk(r.cssRules, l2); if (f) return f; }
        }
        return null;
      };
      const f = walk(sheet.cssRules, []);
      if (f) return f;
    }
    return { found: false };
  };
  result.hiddenRule = checkLayer('.hidden');
  return result;
}

async () => {
  const W = 1024;
  const REM = 16;
  document.getElementById('__bpsim')?.remove();
  document.getElementById('__bpsim-style')?.remove();

  const widthRules = [];
  const parse = (mt) => {
    const m = mt.match(/(?:width\s*>=\s*|min-width:\s*)([\d.]+)(rem|px)/);
    if (m) return { type: 'min', px: m[2] === 'rem' ? parseFloat(m[1]) * REM : parseFloat(m[1]) };
    const m2 = mt.match(/(?:width\s*<=\s*|max-width:\s*)([\d.]+)(rem|px)/);
    if (m2) return { type: 'max', px: m2[2] === 'rem' ? parseFloat(m2[1]) * REM : parseFloat(m2[1]) };
    return null;
  };
  const collectStyleRules = (ruleList, out) => {
    for (const r of ruleList) {
      if (r instanceof CSSStyleRule) out.push(r.cssText);
      else if (r.cssRules) collectStyleRules(r.cssRules, out);
    }
  };
  const walk = (list) => {
    for (const r of list) {
      if (r instanceof CSSMediaRule) {
        const c = parse(r.media.mediaText);
        if (c && (c.type === 'min' ? W >= c.px : W <= c.px)) collectStyleRules(r.cssRules, widthRules);
        else walk(r.cssRules);
      } else if (r.cssRules) walk(r.cssRules);
    }
  };
  for (const sheet of document.styleSheets) { try { walk(sheet.cssRules); } catch (e) {} }

  const scopeCss = (cssText) => {
    const i = cssText.indexOf('{');
    const sels = cssText.slice(0, i).trim().split(',').map(s => `[data-bpclone] ${s.trim()}`).join(',');
    return sels + cssText.slice(i);
  };
  const styleEl = document.createElement('style');
  styleEl.id = '__bpsim-style';
  styleEl.textContent = widthRules.map(scopeCss).join('\n');
  document.head.appendChild(styleEl);

  const realHeader = document.querySelector('header');
  const container = document.createElement('div');
  container.id = '__bpsim';
  container.setAttribute('data-bpclone', '');
  container.style.cssText = `position:fixed;left:-20000px;top:0;width:${W}px;z-index:999999;`;
  const clone = realHeader.cloneNode(true);
  container.appendChild(clone);
  document.body.appendChild(container);
  await new Promise(r => setTimeout(r, 300));

  const cs = (el) => getComputedStyle(el);
  const headerRect = clone.getBoundingClientRect();
  const overflowX = clone.scrollWidth - clone.clientWidth;

  const logoutBtn = clone.querySelector('button[title="退出登录"]');
  const logoutRect = logoutBtn.getBoundingClientRect();
  const logoutRightRel = +(logoutRect.right - headerRect.left).toFixed(2);

  const badge = [...clone.querySelectorAll('span')].find(s => s.textContent.includes('NL2SQL Pro'));
  const badgeDisplay = badge ? cs(badge).display : 'NOT-FOUND';

  const unitSelect = clone.querySelector('select[data-testid="global-amount-unit-select"]');
  const unitWrap = unitSelect ? unitSelect.parentElement : null;
  const unitDisplay = unitWrap ? cs(unitWrap).display : 'NOT-FOUND';

  const dsSelect = clone.querySelector('select[data-testid="datasource-select"]');
  const dsWrap = dsSelect ? dsSelect.parentElement : null;

  const subtitle = clone.querySelector('p');
  const subtitleDisplay = subtitle ? cs(subtitle).display : 'N/A';

  // Range.getClientRects 折行检测
  const wrapped = [], checked = [];
  const walker = document.createTreeWalker(clone, NodeFilter.SHOW_TEXT);
  let node; const range = document.createRange();
  while ((node = walker.nextNode())) {
    const txt = node.textContent;
    if (!txt || !txt.trim()) continue;
    const parent = node.parentElement;
    if (!parent || parent.closest('select,option,script,style')) continue;
    let anc = parent, hidden = false;
    while (anc && anc !== container) { const d = cs(anc); if (d.display === 'none' || d.visibility === 'hidden') { hidden = true; break; } anc = anc.parentElement; }
    if (hidden) continue;
    range.selectNodeContents(node);
    const rects = range.getClientRects();
    checked.push({ text: txt.trim().slice(0, 34), lines: rects.length });
    if (rects.length > 1) wrapped.push({ text: txt.trim().slice(0, 34), lines: rects.length });
  }

  // 缩放回可视区供截图
  const scale = Math.min(1, (window.innerWidth - 8) / W);
  container.style.left = '4px';
  container.style.transform = `scale(${scale})`;
  container.style.transformOrigin = 'top left';
  container.style.background = getComputedStyle(document.body).backgroundColor || '#0f172a';
  container.style.outline = '2px solid #22d3ee';

  return {
    targetWidth: W,
    appliedStyleRules: widthRules.length,
    header: { clientWidth: clone.clientWidth, scrollWidth: clone.scrollWidth, overflowX },
    logoutBtn: { rightRelToHeader: logoutRightRel, fullyVisible: logoutRightRel <= W },
    versionBadge: { display: badgeDisplay, visible: badgeDisplay !== 'none' },
    amountUnitSelector: { display: unitDisplay, visible: unitDisplay === 'flex' },
    datasourceSwitcher: { display: dsWrap ? cs(dsWrap).display : 'N/A' },
    subtitle: { display: subtitleDisplay },
    textWrap: { visibleTextNodes: checked.length, wrappedCount: wrapped.length, wrapped, checked }
  };
}

