() => {
  const container = document.getElementById('__bpsim');
  const clone = container.querySelector('header');
  const headerRect = clone.getBoundingClientRect();
  const W = 1024;
  const items = [];
  const walk = (el, depth) => {
    const r = el.getBoundingClientRect();
    if (r.width > 0 && getComputedStyle(el).display !== 'none') {
      const relRight = +(r.right - headerRect.left).toFixed(1);
      const relLeft = +(r.left - headerRect.left).toFixed(1);
      if (depth <= 2 || relRight > W - 1) {
        items.push({
          depth, tag: el.tagName.toLowerCase(),
          cls: (el.className.baseVal !== undefined ? el.className.baseVal : el.className || '').toString().slice(0, 60),
          text: (el.childNodes.length === 1 && el.firstChild.nodeType === 3) ? el.textContent.trim().slice(0, 20) : '',
          left: relLeft, right: relRight, over: relRight > W + 0.5
        });
      }
    }
    for (const c of el.children) walk(c, depth + 1);
  };
  walk(clone, 0);
  const left = clone.children[0].getBoundingClientRect();
  const right = clone.children[1].getBoundingClientRect();
  return {
    leftBlock: { width: +(left.width).toFixed(1), right: +(left.right - headerRect.left).toFixed(1) },
    rightBlock: { width: +(right.width).toFixed(1), right: +(right.right - headerRect.left).toFixed(1), scrollWidth: clone.children[1].scrollWidth },
    headerPadding: getComputedStyle(clone).paddingLeft + ' / ' + getComputedStyle(clone).paddingRight,
    overflowingElements: items.filter(i => i.over),
    topLevel: items.filter(i => i.depth <= 1)
  };
}

() => {
  const container = document.getElementById('__bpsim');
  const clone = container.querySelector('header');
  const right = clone.children[1];
  const left = clone.children[0];
  const rows = [];
  for (const c of right.children) {
    const d = getComputedStyle(c).display;
    rows.push({
      tag: c.tagName.toLowerCase(),
      cls: (c.className || '').toString().slice(0, 50),
      display: d,
      offsetWidth: c.offsetWidth,
      scrollWidth: c.scrollWidth
    });
  }
  return {
    headerClientWidth: clone.clientWidth,
    headerScrollWidth: clone.scrollWidth,
    leftBlock: { offsetWidth: left.offsetWidth, scrollWidth: left.scrollWidth },
    rightBlock: { offsetWidth: right.offsetWidth, scrollWidth: right.scrollWidth },
    rightChildren: rows,
    rightChildrenSum: rows.filter(r => r.display !== 'none').reduce((s, r) => s + r.offsetWidth, 0)
  };
}

